/bin/bash -lc "python3 - <<'PY'
import pathlib
import subprocess
import tempfile
source = r'''
#include \"service.hpp\"
#include <cassert>
#include <string>
int main() {
    for (int port = 1; port <= 65535; ++port) {
        const auto s = std::to_string(port);
        assert(parsePort(s) == port);
        assert(parsePort(\"000\" + s) == port);
    }
    for (const auto& s : {std::string(), std::string(\"0\"), std::string(\"000\"),
         std::string(\"65536\"), std::string(\"2147483647\"), std::string(\"2147483648\"),
         std::string(10000, '9'), std::string(\"+1\"), std::string(\"-1\"),
         std::string(\" 1\"), std::string(\"1 \"), std::string(\"1\\n\"),
         std::string(\"1.0\"), std::string(\"0x10\"), std::string(\"1x\"),
         std::string(\"1\\0\", 2), std::string(\"\\xff\", 1), std::string(\"\\xd9\\xa1\", 2)}) {
        assert(parsePort(s) == -1);
    }
    assert(parsePort(std::string(10000, '0') + \"65535\") == 65535);
    for (int byte = 0; byte <= 255; ++byte) {
        if (byte >= '0' && byte <= '9') continue;
        assert(parsePort(std::string(\"1\") + static_cast<char>(byte)) == -1);
    }
}
'''
with tempfile.TemporaryDirectory(prefix='parse-port-check-') as tmp:
    binary = str(pathlib.Path(tmp) / 'check')
    subprocess.run(['c++', '-std=c++17', '-Wall', '-Wextra', '-Werror', '-fsanitize=undefined', '-I', '.', '-x', 'c++', '-o', binary, '-'], input=source, text=True, check=True)
    subprocess.run([binary], check=True)
print('Exhaustive valid-port and malformed/overflow checks passed under UBSan.')
PY"

